Q(bi('Ida e volta','Out and back'),bi('Você caminha 8 m para leste e 3 m para oeste. Qual é o deslocamento, em metros, adotando leste positivo?','You walk 8 m east and 3 m west. What is your displacement in meters, taking east as positive?'),5,bi('Δx = +8 − 3 = +5 m, para leste. A distância total é outra grandeza: 8 + 3 = 11 m.','Δx = +8 − 3 = +5 m, east. Total distance is a different quantity: 8 + 3 = 11 m.')),
Q(bi('Freando a bicicleta','Braking a bicycle'),bi('Uma bicicleta passa de 12 m/s para 4 m/s em 4 s. Qual é a aceleração média em m/s²? Considere o sentido inicial positivo.','A bicycle slows from 12 m/s to 4 m/s in 4 s. What is its average acceleration in m/s²? Take the initial direction as positive.'),-2,bi('aₘ = (vfinal − vinicial)/Δt = (4 − 12)/4 = −2 m/s². O sinal negativo indica aceleração oposta à velocidade neste caso.','aavg = (vfinal − vinitial)/Δt = (4 − 12)/4 = −2 m/s². Here the negative sign means acceleration opposite to velocity.')),
Q(bi('Área sob o gráfico','Area under the graph'),bi('Um gráfico velocidade × tempo mostra v = 3 m/s constante entre 0 e 6 s. Qual é o deslocamento em metros?','A velocity–time graph shows constant v = 3 m/s from 0 to 6 s. What is the displacement in meters?'),18,bi('A área sob o gráfico é um retângulo: base 6 s × altura 3 m/s = 18 m.','The area under the graph is a rectangle: width 6 s × height 3 m/s = 18 m.')),
Q(bi('Duas bolas em queda','Two falling balls'),bi('Uma bola pesada e outra leve são soltas juntas da mesma altura, no vácuo e do repouso. Qual chega primeiro?','A heavy ball and a light ball are released together from rest at the same height in a vacuum. Which arrives first?'),1,bi('Sem resistência do ar, ambas têm a mesma aceleração gravitacional no mesmo local. A massa não altera o tempo de queda nesse modelo.','Without air resistance, both have the same gravitational acceleration at the same location. Mass does not change fall time in this model.'),[bi('A mais pesada.','The heavier one.'),bi('As duas chegam juntas.','They arrive together.'),bi('A mais leve.','The lighter one.')])
