Q(bi('Trabalho contra o movimento','Work against motion'),bi('Uma força de atrito constante de 4 N atua contra um deslocamento de 5 m. Qual é o trabalho do atrito em joules?','A constant friction force of 4 N acts against a displacement of 5 m. What is friction’s work in joules?'),-20,bi('W = Fd cos(180°) = 4 × 5 × (−1) = −20 J. O sinal negativo indica retirada de energia mecânica.','W = Fd cos(180°) = 4 × 5 × (−1) = −20 J. The negative sign indicates removal of mechanical energy.')),
Q(bi('A mochila na prateleira','A backpack on a shelf'),bi('Uma mochila de 3 kg está 2 m acima do chão. Use g = 10 m/s² e energia potencial zero no chão. Qual é Eₚ em joules?','A 3 kg backpack is 2 m above the floor. Use g = 10 m/s² and zero potential energy at the floor. What is Eₚ in joules?'),60,bi('Eₚ = mgh = 3 × 10 × 2 = 60 J. O valor depende do nível de referência escolhido.','Eₚ = mgh = 3 × 10 × 2 = 60 J. The value depends on the chosen reference level.')),
Q(bi('Energia guardada na mola','Energy stored in a spring'),bi('Uma mola ideal tem k = 200 N/m e deformação de 0,2 m. Qual energia elástica ela armazena, em joules?','An ideal spring has k = 200 N/m and deformation of 0.2 m. How much elastic energy does it store, in joules?'),4,bi('Eₑ = ½kx² = ½ × 200 × 0,2² = 100 × 0,04 = 4 J.','Eₑ = ½kx² = ½ × 200 × 0.2² = 100 × 0.04 = 4 J.')),
Q(bi('Onde foi parar a energia?','Where did the energy go?'),bi('Um motor recebe 500 J e fornece 350 J de trabalho útil. Qual é seu rendimento, em porcentagem? Digite apenas o número.','A motor receives 500 J and provides 350 J of useful work. What is its efficiency as a percentage? Enter only the number.'),70,bi('η = 350/500 = 0,70 = 70%. Os 150 J restantes não desaparecem: são transferidos de outras formas, como calor.','η = 350/500 = 0.70 = 70%. The remaining 150 J do not disappear: they are transferred in other forms, such as heat.'))
